-- The tables bmo-job owns, on PostgreSQL (docs/schema.md). Each table's columns, in order, are the same
-- as on SQLite; `rowid` is PostgreSQL's stand-in for SQLite's own row number.

CREATE TABLE "todos" (
  "id" bigint GENERATED BY DEFAULT AS IDENTITY,
  "title" text NOT NULL,
  "instruction" text NOT NULL,
  "requester" text NOT NULL,
  "requester_id" bigint,
  "chat_id" bigint,
  "approved" bigint NOT NULL DEFAULT 0,
  "done" bigint NOT NULL DEFAULT 0,
  "priority" bigint NOT NULL,
  "status" text NOT NULL,
  "model" text,
  "note" text,
  "report" text,
  "unfinished" text,
  "unfinished_resolved_at" bigint,
  "unfinished_resolution" text,
  "created_at" bigint NOT NULL,
  "done_at" bigint,
  "held_at" bigint,
  "held_reason" text,
  "held_kind" text,
  "resume_after" bigint,
  "merged_into" bigint,
  "merged_at" bigint,
  "worker" text,
  "cowork" bigint,
  "repairs_todo_id" bigint,
  "resume_after_deploy" text,
  "approved_via" text,
  "agent" text,
  "impact" text,
  "job_impact" text,
  "brief" text,
  "brief_korean" text,
  rowid bigint GENERATED ALWAYS AS ("id") STORED,
  PRIMARY KEY ("id")
);
CREATE INDEX "todos_merged_into" ON "todos" (merged_into);
CREATE INDEX "todos_queue" ON "todos" (done, approved, priority, id);
CREATE INDEX "todos_repairs_todo_id" ON "todos" (repairs_todo_id);

CREATE FUNCTION todos_merge_refusal() RETURNS trigger LANGUAGE plpgsql AS $$
BEGIN
  IF NEW.merged_into = NEW.id THEN
    RAISE EXCEPTION 'todo merge: an item is never merged into itself';
  END IF;
  IF NOT EXISTS (SELECT 1 FROM todos WHERE id = NEW.merged_into) THEN
    RAISE EXCEPTION 'todo merge: the item merged into does not exist';
  END IF;
  IF (SELECT merged_into FROM todos WHERE id = NEW.merged_into) IS NOT NULL THEN
    RAISE EXCEPTION 'todo merge: the item merged into is itself merged';
  END IF;
  IF EXISTS (SELECT 1 FROM todos WHERE merged_into = NEW.id) THEN
    RAISE EXCEPTION 'todo merge: other items are merged into this one';
  END IF;
  RETURN NEW;
END
$$;

CREATE FUNCTION todos_merge_delete_refusal() RETURNS trigger LANGUAGE plpgsql AS $$
BEGIN
  IF EXISTS (SELECT 1 FROM todos WHERE merged_into = OLD.id) THEN
    RAISE EXCEPTION 'todo merge: other items are merged into this one';
  END IF;
  RETURN OLD;
END
$$;

CREATE TRIGGER todos_merge_insert BEFORE INSERT ON todos
  FOR EACH ROW WHEN (NEW.merged_into IS NOT NULL)
  EXECUTE FUNCTION todos_merge_refusal();

CREATE TRIGGER todos_merge_update BEFORE UPDATE OF merged_into ON todos
  FOR EACH ROW WHEN (NEW.merged_into IS NOT NULL AND NEW.merged_into IS DISTINCT FROM OLD.merged_into)
  EXECUTE FUNCTION todos_merge_refusal();

CREATE TRIGGER todos_merge_delete BEFORE DELETE ON todos
  FOR EACH ROW EXECUTE FUNCTION todos_merge_delete_refusal();

CREATE TABLE "todo_notes" (
  "id" bigint GENERATED BY DEFAULT AS IDENTITY,
  "todo_id" bigint NOT NULL,
  "author" text NOT NULL,
  "author_id" bigint,
  "text" text NOT NULL,
  "added_at" bigint NOT NULL,
  "job_id" bigint,
  "delivered_at" bigint,
  "removed_at" bigint,
  "removed_by" text,
  "kind" text,
  rowid bigint GENERATED ALWAYS AS ("id") STORED,
  PRIMARY KEY ("id")
);
CREATE INDEX "todo_notes_item" ON "todo_notes" (todo_id, id);

CREATE TABLE "todo_sources" (
  "todo_id" bigint NOT NULL,
  "source_todo_id" bigint NOT NULL,
  rowid bigint GENERATED BY DEFAULT AS IDENTITY UNIQUE,
  PRIMARY KEY ("todo_id", "source_todo_id")
);
CREATE INDEX "todo_sources_source" ON "todo_sources" (source_todo_id);

CREATE TABLE "todo_approvals" (
  "id" bigint GENERATED BY DEFAULT AS IDENTITY,
  "todo_id" bigint NOT NULL,
  "approved" bigint NOT NULL,
  "via" text,
  "who_kind" text NOT NULL,
  "who" text NOT NULL,
  "road" text NOT NULL,
  "at" bigint NOT NULL,
  rowid bigint GENERATED ALWAYS AS ("id") STORED,
  PRIMARY KEY ("id")
);
CREATE INDEX "todo_approvals_item" ON "todo_approvals" (todo_id, id);

CREATE TABLE "work_orders" (
  "todo_id" bigint GENERATED BY DEFAULT AS IDENTITY,
  "body" text NOT NULL,
  rowid bigint GENERATED ALWAYS AS ("todo_id") STORED,
  PRIMARY KEY ("todo_id")
);
CREATE INDEX "work_orders_status" ON "work_orders" ((body::JSON ->> 'status'));

CREATE TABLE "work_order_locks" (
  "todo_id" bigint,
  "host" text NOT NULL,
  "pid" bigint NOT NULL,
  "start" text NOT NULL,
  "token" text NOT NULL,
  "taken_at" bigint NOT NULL,
  rowid bigint GENERATED BY DEFAULT AS IDENTITY UNIQUE,
  PRIMARY KEY ("todo_id")
);

CREATE TABLE "jobs" (
  "id" bigint GENERATED BY DEFAULT AS IDENTITY,
  "chat_id" bigint NOT NULL,
  "unit" text NOT NULL,
  "launched_at" bigint NOT NULL,
  "prompt" text NOT NULL,
  "finished_at" bigint,
  "report" text,
  "ok" bigint,
  "started_by" text,
  "todo_id" bigint,
  "activity_version" bigint,
  "model" text,
  "outcome" text,
  "execution_mode" text,
  "execution_model" text,
  "execution_effort" text,
  "execution_tier" text,
  "execution_upstream" text,
  "worker" text,
  "purpose" text,
  "prompt_english" text,
  "prompt_korean" text,
  rowid bigint GENERATED ALWAYS AS ("id") STORED,
  PRIMARY KEY ("id")
);
CREATE INDEX "jobs_open" ON "jobs" (id) WHERE finished_at IS NULL;
CREATE INDEX "jobs_todo" ON "jobs" (todo_id);
CREATE INDEX "jobs_unit" ON "jobs" (unit, id);
CREATE INDEX "jobs_finished" ON "jobs" (finished_at);
CREATE INDEX "jobs_launched" ON "jobs" (launched_at);
CREATE INDEX "jobs_report" ON "jobs" (length(report), finished_at);

CREATE TABLE "job_spans" (
  "id" bigint GENERATED BY DEFAULT AS IDENTITY,
  "job_id" bigint NOT NULL,
  "todo_id" bigint,
  "kind" text NOT NULL,
  "name" text NOT NULL,
  "seconds" double precision NOT NULL,
  "times" bigint NOT NULL DEFAULT 1,
  "tokens" bigint,
  "input_tokens" bigint,
  "output_tokens" bigint,
  "cache_read_tokens" bigint,
  "cache_write_tokens" bigint,
  rowid bigint GENERATED ALWAYS AS ("id") STORED,
  PRIMARY KEY ("id")
);
CREATE INDEX "job_spans_job" ON "job_spans" (job_id);
CREATE INDEX "job_spans_todo" ON "job_spans" (todo_id);

CREATE TABLE "job_questions" (
  "id" bigint GENERATED BY DEFAULT AS IDENTITY,
  "job_id" bigint,
  "todo_id" bigint NOT NULL,
  "chat_id" bigint NOT NULL,
  "question" text NOT NULL,
  "options" text NOT NULL,
  "recommended" bigint NOT NULL,
  "why" text NOT NULL,
  "asked_at" bigint NOT NULL,
  "due_at" bigint NOT NULL,
  "chosen" bigint,
  "answer" text,
  "paused_left" bigint,
  "settled_at" bigint,
  "settled_by" text,
  "talks" bigint NOT NULL DEFAULT 0,
  rowid bigint GENERATED ALWAYS AS ("id") STORED,
  PRIMARY KEY ("id")
);
CREATE INDEX "job_questions_open" ON "job_questions" (chat_id, settled_at);

CREATE TABLE "question_talk" (
  "id" bigint GENERATED BY DEFAULT AS IDENTITY,
  "question_id" bigint NOT NULL,
  "by" text NOT NULL,
  "text" text NOT NULL,
  "said_at" bigint NOT NULL,
  "heard_at" bigint,
  rowid bigint GENERATED ALWAYS AS ("id") STORED,
  PRIMARY KEY ("id")
);
CREATE INDEX "question_talk_question" ON "question_talk" (question_id);

CREATE TABLE "checkout_leases" (
  "worker" text,
  "job_id" bigint NOT NULL,
  "taken_at" bigint NOT NULL,
  rowid bigint GENERATED BY DEFAULT AS IDENTITY UNIQUE,
  PRIMARY KEY ("worker")
);

CREATE TABLE "branch_agents" (
  "pool" text NOT NULL DEFAULT '',
  "slot" bigint NOT NULL,
  "mode" text NOT NULL,
  "model" text NOT NULL,
  "role" text NOT NULL,
  "upstream" text NOT NULL DEFAULT '',
  "prefix_digest" text NOT NULL DEFAULT '',
  "last_reply_at" bigint NOT NULL,
  rowid bigint GENERATED BY DEFAULT AS IDENTITY UNIQUE,
  PRIMARY KEY ("pool", "slot", "mode", "model", "upstream")
);

CREATE TABLE "session_work_items" (
  "session_id" text,
  "todo_id" bigint NOT NULL,
  "served_at" bigint NOT NULL,
  rowid bigint GENERATED BY DEFAULT AS IDENTITY UNIQUE,
  PRIMARY KEY ("session_id")
);

CREATE TABLE "session_work_results" (
  "session_id" text NOT NULL,
  "result" text NOT NULL,
  "version" text NOT NULL,
  "loaded_at" bigint NOT NULL,
  rowid bigint GENERATED BY DEFAULT AS IDENTITY UNIQUE,
  PRIMARY KEY ("session_id", "result")
);

CREATE TABLE "live_claude_openings" (
  "id" bigint GENERATED BY DEFAULT AS IDENTITY,
  "job_id" bigint NOT NULL,
  "todo_id" bigint,
  "purpose" text NOT NULL,
  "opened_at" bigint NOT NULL,
  rowid bigint GENERATED ALWAYS AS ("id") STORED,
  PRIMARY KEY ("id")
);
CREATE INDEX "live_claude_openings_job" ON "live_claude_openings" (job_id);

CREATE TABLE "live_claude_runs" (
  "id" bigint GENERATED BY DEFAULT AS IDENTITY,
  "opening_id" bigint NOT NULL,
  "what" text NOT NULL,
  "ran_at" bigint NOT NULL,
  rowid bigint GENERATED ALWAYS AS ("id") STORED,
  PRIMARY KEY ("id")
);
CREATE INDEX "live_claude_runs_opening" ON "live_claude_runs" (opening_id);

CREATE TABLE "clock_holds" (
  "id" bigint GENERATED BY DEFAULT AS IDENTITY,
  "run" text NOT NULL,
  "agent" text NOT NULL,
  "what" text NOT NULL,
  "clock" text NOT NULL,
  "clock_ms" bigint NOT NULL,
  "started_at" bigint NOT NULL,
  "last_activity_at" bigint,
  "last_activity" text,
  "asked_at" bigint NOT NULL,
  "answer_by" bigint NOT NULL,
  "instruction_id" bigint,
  "verdict" text,
  "keep_until" bigint,
  "decided_by" text,
  "why" text,
  "decided_at" bigint,
  "closed" text,
  "closed_at" bigint,
  rowid bigint GENERATED ALWAYS AS ("id") STORED,
  PRIMARY KEY ("id")
);

CREATE TABLE "workers" (
  "name" text,
  "label" text,
  "cwd" text,
  "icon" text,
  "builtin" bigint NOT NULL DEFAULT 0,
  "preamble" text,
  "dev_command" text,
  "support_count" bigint NOT NULL DEFAULT 0,
  "support_keepalive" bigint NOT NULL DEFAULT 0,
  "support_of" text,
  "support_slot" bigint,
  "node" text,
  "role" text,
  "resting_since" bigint,
  "created_at" bigint NOT NULL,
  rowid bigint GENERATED BY DEFAULT AS IDENTITY UNIQUE,
  PRIMARY KEY ("name")
);

CREATE TABLE "settings" (
  "key" text,
  "value" text NOT NULL,
  rowid bigint GENERATED BY DEFAULT AS IDENTITY UNIQUE,
  PRIMARY KEY ("key"),
  CONSTRAINT "settings_key_owned" CHECK (
    "key" IN (
      'queue_paused', 'deploy_hold', 'deploy_waits_on', 'machine_launch_held', 'failure_orders',
      'job_queue_told', 'work_retry_model'
    )
    OR "key" ~ '^(job_stop|job_route_attempts|job_route_block|job_report_waiting|job_ending_waiting|job_report_roads|job_wait|job_command|job_quiet_told|job_spin_told|job_queue_waiting|job_queue_waiting_told|todo_repair_ceiling_told):.'
  )
);
